fn parse_on_delete(value: Option<&str>) -> Result<OnDelete, McpError> {
    match value.unwrap_or("cascade").to_ascii_lowercase().as_str() {
        "cascade" => Ok(OnDelete::Cascade),
        "set_null" => Ok(OnDelete::SetNull),
        "restrict" => Ok(OnDelete::Restrict),
        "no_action" => Ok(OnDelete::NoAction),
        "set_default" => Ok(OnDelete::SetDefault),
        other => Err(McpError::InvalidParam {
            name: "on_delete",
            detail: format!("unknown action `{other}`"),
        }),
    }
}

fn parse_on_update(value: Option<&str>) -> Result<OnUpdate, McpError> {
    match value.unwrap_or("cascade").to_ascii_lowercase().as_str() {
        "cascade" => Ok(OnUpdate::Cascade),
        "set_null" => Ok(OnUpdate::SetNull),
        "restrict" => Ok(OnUpdate::Restrict),
        "no_action" => Ok(OnUpdate::NoAction),
        "set_default" => Ok(OnUpdate::SetDefault),
        other => Err(McpError::InvalidParam {
            name: "on_update",
            detail: format!("unknown action `{other}`"),
        }),
    }
}

/// Lowercase, non-alphanumerics to `-`, collapsed and trimmed.
pub fn slugify(value: &str) -> String {
    let slug = value
        .to_lowercase()
        .chars()
        .map(|c| if c.is_alphanumeric() { c } else { '-' })
        .collect::<String>()
        .split('-')
        .filter(|part| !part.is_empty())
        .collect::<Vec<_>>()
        .join("-");
    if slug.is_empty() {
        "page".into()
    } else {
        slug
    }
}

/// Convenience used by the pipeline: the type tag of a field, for context cards.
pub fn field_type_name(field: &EntityField) -> String {
    type_tag(&field.field_type)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn type_tags_expand_to_the_canonical_shape() {
        let field_type = parse_entity_field_type(&json!("Decimal")).unwrap();
        assert_eq!(
            field_type,
            EntityFieldType::Decimal {
                precision: 12,
                scale: 2
            }
        );
        let with_config =
            parse_entity_field_type(&json!({"type": "String", "max_length": 80})).unwrap();
        assert_eq!(
            with_config,
            EntityFieldType::String {
                max_length: Some(80)
            }
        );
    }

    #[test]
    fn an_unknown_field_type_is_a_clear_error() {
        let error = parse_entity_field_type(&json!("Money")).unwrap_err();
        assert!(error.to_string().contains("field_type"));
    }

    #[test]
    fn form_field_types_default_their_options() {
        let field_type = parse_form_field_type(&json!("Select")).unwrap();
        assert!(matches!(field_type, FieldType::Select { .. }));
    }

    #[test]
    fn components_get_defaults_or_a_helpful_error() {
        assert!(matches!(
            build_component("Container", None).unwrap(),
            ComponentType::Container { .. }
        ));
        let error = build_component("Chart", None).unwrap_err();
        assert!(error.to_string().contains("config"));
    }

    #[test]
    fn a_parent_that_cannot_hold_children_is_rejected() {
        let mut parent = PageComponent {
            id: ComponentId::new(),
            component: ComponentType::Divider {
                orientation: "horizontal".into(),
                dashed: false,
                text: None,
            },
            props: Default::default(),
            bindings: Vec::new(),
            events: Vec::new(),
            conditions: Vec::new(),
            slots: Default::default(),
            style_overrides: Default::default(),
        };
        assert!(attach_child(&mut parent, ComponentId::new(), None).is_err());
    }

    #[test]
    fn slots_accept_children_even_when_the_variant_has_none() {
        let mut parent = PageComponent {
            id: ComponentId::new(),
            component: ComponentType::Divider {
                orientation: "horizontal".into(),
                dashed: false,
                text: None,
            },
            props: Default::default(),
            bindings: Vec::new(),
            events: Vec::new(),
            conditions: Vec::new(),
            slots: Default::default(),
            style_overrides: Default::default(),
        };
        attach_child(&mut parent, ComponentId::new(), Some("header".into())).unwrap();
        assert_eq!(parent.slots["header"].len(), 1);
    }

    #[test]
    fn slugify_never_returns_an_empty_path_segment() {
        assert_eq!(slugify("Expense Approval"), "expense-approval");
        assert_eq!(slugify("***"), "page");
    }
}
